// Bounded poll: $runIndex increments each loop pass through this node.
const root = $input.first().json;
const d = root.data || root;
const status = d.status || 'UNKNOWN';
const attempt = $runIndex + 1;
const terminal = ['SUCCEEDED', 'FAILED', 'TIMED-OUT', 'ABORTED'].includes(status);
const giveUp = attempt >= 20; // ~20 polls * 30s = ~10 min ceiling
return [{ json: {
  status,
  datasetId: d.defaultDatasetId || $('Prep Poll').item.json.datasetId,
  attempt,
  succeeded: status === 'SUCCEEDED',
  proceed: terminal || giveUp
} }];

// Flatten whatever shape the dataset endpoint returns into one row per place,
// clean phone + website, dedupe on place_id, and carry the counts the
// execution panel should show (rows_seen before dedupe, rows_written after).
const cfg = $('Config').first().json;

let raw = [];
for (const it of $input.all()) {
  const b = it.json;
  if (Array.isArray(b)) raw.push(...b);
  else if (b && Array.isArray(b.data)) raw.push(...b.data);
  else if (b) raw.push(b);
}

// Digits only; anything shorter than 10 digits is not a dialable number.
function cleanPhone(v) {
  const digits = String(v || '').replace(/[^0-9]/g, '');
  return digits.length >= 10 ? digits : null;
}

// Host only, via string ops. The Code sandbox has no URL() / URLSearchParams.
function cleanHost(v) {
  let w = String(v || '').trim();
  if (!w) return null;
  w = w.replace(/^https?:\/\//i, '');
  w = w.split('/')[0].split('?')[0].split('#')[0];
  w = w.split('@').pop().split(':')[0];
  w = w.replace(/^www\./i, '').toLowerCase();
  return w || null;
}

const candidates = raw
  .filter(x => x && x.placeId)
  .filter(x => {
    // category gate: never harvest obvious non-operators
    const cat = String(x.categoryName || '').toLowerCase();
    return !/(non.?profit|supplier|wholesal|distribut|charity|store)/.test(cat);
  });

const rows_seen = candidates.length;
const seen = new Set();
const out = [];
for (const x of candidates) {
  const id = String(x.placeId);
  if (seen.has(id)) continue; // same place on two result pages lands once
  seen.add(id);
  out.push({
    place_id: id,
    name: x.title || x.name || 'Unknown',
    category: x.categoryName || null,
    city: x.city || cfg.city || null,
    state: x.state || cfg.state || null,
    phone: cleanPhone(x.phone || x.phoneUnformatted),
    website: cleanHost(x.website),
    has_website: !!x.website,
    maps_rating: (x.totalScore ?? null),
    review_count: (x.reviewsCount ?? null),
    run_id: cfg.run_id
  });
}
const rows_written = out.length;
if (rows_written === 0) throw new Error('Apify returned 0 usable places for query "' + cfg.query + '"');
return out.map(r => ({ json: Object.assign({ rows_seen, rows_written }, r) }));

// One summary item, read straight off the execution panel.
// seconds = wall clock from the Config node (started_at) to now.
const cfg = $('Config').first().json;
const norm = $('Normalize + Dedupe').first().json;
const upserted = $input.all().length; // one RETURNING row per UPSERT
const started = new Date(cfg.started_at).getTime();
const seconds = Math.round((Date.now() - started) / 100) / 10;
return [{ json: {
  run_id: cfg.run_id,
  query: cfg.query,
  rows_seen: norm.rows_seen,
  rows_written: upserted,
  rows_deduped: norm.rows_seen - upserted,
  seconds
} }];
